[GUPPricingAttributeFieldsDiscovery(fieldStr(EcoResConfiguration, Name))]
internal class GUPPricingAttributeEcoResProductVariantConfigConfig extends GUPPricingAttributeEcoResProductVariantConfig
    implements GUPIPricingAttribute, GUPIPricingAttributeEcoResProductVariantDimensionValue
