public anytype getValueOfAttribute(Common _pricingObject)
{
    RefRecId configId = this.getTableRecord(_pricingObject).Configuration;
    return EcoResConfiguration::find(configId).Name;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        QueryBuildDataSource qbdsConfig = _qbds.addDataSource(tableNum(EcoResConfiguration));
        qbdsConfig.joinMode(JoinMode::InnerJoin);
        qbdsConfig.addLink(fieldNum(EcoResProductVariantConfiguration, Configuration), fieldNum(EcoResConfiguration, RecId));
        qbdsConfig.addRange(fieldNum(EcoResConfiguration, Name)).value(queryValue(_value));
    }

    public void buildEcoResProductVariantQuery(Query _query, anytype _value, QueryBuildDataSource _qbds)
    {
        if (_qbds.table() != tableNum(EcoResDistinctProductVariant))
        {
            return;
        }

        QueryBuildDataSource qbdsVariantConfiguration, qbdsConfiguration;
        qbdsVariantConfiguration = _qbds.addDataSource(tableNum(EcoResProductVariantConfiguration));
        qbdsVariantConfiguration.joinMode(JoinMode::ExistsJoin);
        qbdsVariantConfiguration.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantConfiguration, DistinctProductVariant));

        qbdsConfiguration = qbdsVariantConfiguration.addDataSource(tableNum(EcoResConfiguration));
        qbdsConfiguration.joinMode(JoinMode::InnerJoin);
        qbdsConfiguration.addLink(fieldNum(EcoResProductVariantConfiguration,Configuration), fieldNum(EcoResConfiguration, RecId));

        qbdsConfiguration.addRange(fieldNum(EcoResConfiguration, Name)).value(queryValue(_value));
    }
